/* DSE Writing Part B: imported from supplied PDFs. */
window.EDMUND_DSE_WRITING_PART_B_2022_SEED = {"dse/writing/part-b/2022/Q4":[{"front":"end-of-season dinner","meaning":"季末晚宴","examples":[{"en":"We are sitting together at this end-of-season dinner.","zh":"我們正一起坐在這場季末晚宴上。"},{"en":"An end-of-season dinner is a meal held after a sports season to thank people and reflect on the year.","zh":"季末晚宴，是在運動賽季結束後舉行的飯聚，用來感謝他人和回顧一年。"},{"en":"The basketball team invited coaches and parents to its end-of-season dinner.","zh":"籃球隊邀請教練和家長參加季末晚宴。"},{"en":"An end-of-season dinner helps players remember both victories and difficult moments.","zh":"季末晚宴幫助球員記住勝利，也記住艱難時刻。"},{"en":"At the end-of-season dinner, the team celebrated effort rather than only medals.","zh":"在季末晚宴上，隊伍慶祝努力，而不只是獎牌。"}],"source":"2022 Q4.pdf","sourcePage":1},{"front":"the noise of the final has faded","meaning":"決賽的喧鬧已經淡去","examples":[{"en":"The noise of the final has faded, but its meaning has not.","zh":"決賽的喧鬧已經淡去，但它的意義沒有消失。"},{"en":"The noise of the final has faded means the excitement and loud sounds of the final are now gone.","zh":"決賽的喧鬧已經淡去，意思是決賽的興奮和巨大聲音已經過去。"},{"en":"After the match, the cheers faded, but the players still remembered the feeling.","zh":"比賽後，歡呼聲淡去，但球員仍記得那份感覺。"},{"en":"Noise fades quickly, but important lessons can remain for years.","zh":"喧鬧很快會淡去，但重要課題可以留下多年。"},{"en":"The final’s noise faded, yet the team still carried its message.","zh":"決賽的喧鬧淡去了，但隊伍仍承載它的信息。"}],"source":"2022 Q4.pdf","sourcePage":1},{"front":"its meaning has not","meaning":"它的意義沒有消失","examples":[{"en":"The final is over, but its meaning has not faded.","zh":"決賽結束了，但它的意義沒有消失。"},{"en":"Its meaning has not means the importance or lesson of something still remains.","zh":"它的意義沒有消失，意思是某事的重要性或課題仍然存在。"},{"en":"The speech ended, but its meaning stayed with the students.","zh":"演講結束了，但它的意義留在學生心中。"},{"en":"A result may pass quickly, but its meaning can shape future effort.","zh":"結果可能很快過去，但它的意義可以塑造日後努力。"},{"en":"The final’s meaning has not disappeared because the team learned from it.","zh":"決賽的意義沒有消失，因為隊伍從中學習。"}],"source":"2022 Q4.pdf","sourcePage":1},{"front":"a few weeks ago","meaning":"幾星期前","examples":[{"en":"A few weeks ago, we played in the inter-school championship final.","zh":"幾星期前，我們參加了校際錦標賽決賽。"},{"en":"A few weeks ago means several weeks before now.","zh":"幾星期前，意思是現在之前的數個星期。"},{"en":"A few weeks ago, the team was still training every morning.","zh":"幾星期前，隊伍仍每天早上訓練。"},{"en":"Looking back to a few weeks ago can help people understand how much has changed.","zh":"回望幾星期前，可以幫助人理解改變有多大。"},{"en":"A few weeks ago, the players were focused on winning; now they are focused on growing.","zh":"幾星期前，球員專注於勝利；現在他們專注於成長。"}],"source":"2022 Q4.pdf","sourcePage":1},{"front":"inter-school championship final","meaning":"校際錦標賽決賽","examples":[{"en":"We walked into the inter-school championship final with pride.","zh":"我們自豪地走進校際錦標賽決賽。"},{"en":"An inter-school championship final is the last match of a competition between schools.","zh":"校際錦標賽決賽，是學校之間比賽的最後一場賽事。"},{"en":"Students may train for months before reaching an inter-school championship final.","zh":"學生可能訓練數月才打入校際錦標賽決賽。"},{"en":"Such a final is important because it represents the highest stage of the school season.","zh":"這樣的決賽很重要，因為它代表學校賽季的最高舞台。"},{"en":"The team entered the inter-school championship final carrying its school’s hopes.","zh":"隊伍走進校際錦標賽決賽，肩負學校的期望。"}],"source":"2022 Q4.pdf","sourcePage":1},{"front":"carry our school’s hopes on our backs","meaning":"肩負學校的期望","examples":[{"en":"We carried our school’s hopes on our backs during the final.","zh":"在決賽中，我們肩負學校的期望。"},{"en":"To carry our school’s hopes on our backs means to feel responsible for representing the school’s dreams and support.","zh":"肩負學校的期望，意思是感到自己有責任代表學校的夢想和支持。"},{"en":"A debate team may carry the school’s hopes into a public final.","zh":"辯論隊可能帶着學校的期望走進公開決賽。"},{"en":"This feeling can create pressure, but it can also give players courage.","zh":"這種感覺可以帶來壓力，也可以給球員勇氣。"},{"en":"The players carried their school’s hopes because many students, teachers, and parents believed in them.","zh":"球員肩負學校的期望，因為許多學生、老師和家長都相信他們。"}],"source":"2022 Q4.pdf","sourcePage":1},{"front":"fight, chase, defend and dive","meaning":"奮戰、追趕、防守和撲救","examples":[{"en":"We fought, chased, defended and dived for every loose ball.","zh":"我們為每一個無人控制的球奮戰、追趕、防守和撲救。"},{"en":"Fight, chase, defend and dive describes the full effort players give during a tough match.","zh":"奮戰、追趕、防守和撲救，描述球員在艱難比賽中付出的全部努力。"},{"en":"In a close game, players may fight for space, chase the ball, defend strongly, and dive to save possession.","zh":"在接近的比賽中，球員可能爭位、追球、努力防守並撲救控球權。"},{"en":"These actions show determination because players refuse to give up easy points.","zh":"這些動作顯示決心，因為球員拒絕輕易放棄分數。"},{"en":"The team fought, chased, defended and dived because every ball mattered.","zh":"隊伍奮戰、追趕、防守和撲救，因為每一球都重要。"}],"source":"2022 Q4.pdf","sourcePage":1},{"front":"loose ball","meaning":"無人控制的球","examples":[{"en":"Every player fought hard for every loose ball.","zh":"每位球員都為每一個無人控制的球奮力爭奪。"},{"en":"A loose ball is a ball that no player or team clearly controls.","zh":"無人控制的球，是沒有任何球員或隊伍明確控制的球。"},{"en":"In basketball, a loose ball may roll across the floor after a missed pass.","zh":"在籃球中，失誤傳球後，無人控制的球可能在地上滾動。"},{"en":"Fighting for loose balls shows effort because possession can change quickly.","zh":"爭奪無人控制的球顯示努力，因為控球權可能快速改變。"},{"en":"The team’s attitude was clear whenever a loose ball appeared.","zh":"每當無人控制的球出現，隊伍的態度就很清楚。"}],"source":"2022 Q4.pdf","sourcePage":1},{"front":"in the end","meaning":"最後","examples":[{"en":"In the end, the scoreboard said we came second.","zh":"最後，計分牌顯示我們得第二名。"},{"en":"In the end means finally, after everything has happened.","zh":"最後，意思是在所有事情發生之後，最終。"},{"en":"In the end, the team lost by two points but earned respect.","zh":"最後，隊伍以兩分落敗，但贏得尊重。"},{"en":"This phrase often introduces the final result after a long effort.","zh":"這個短語常在長時間努力後引出最終結果。"},{"en":"In the end, the result was silver, but the season still had value.","zh":"最後，結果是銀牌，但這個賽季仍有價值。"}],"source":"2022 Q4.pdf","sourcePage":1},{"front":"the scoreboard said","meaning":"計分牌顯示","examples":[{"en":"The scoreboard said we came second.","zh":"計分牌顯示我們得第二名。"},{"en":"The scoreboard said means the official display showed the result.","zh":"計分牌顯示，意思是官方顯示屏展示了結果。"},{"en":"The scoreboard said the match was tied with one minute left.","zh":"計分牌顯示比賽在最後一分鐘仍然打和。"},{"en":"A scoreboard can show the result, but not the full story behind it.","zh":"計分牌可以顯示結果，但不能顯示背後的完整故事。"},{"en":"The scoreboard said second place, but the team knew it had grown.","zh":"計分牌顯示第二名，但隊伍知道自己已經成長。"}],"source":"2022 Q4.pdf","sourcePage":1},{"front":"come second","meaning":"得第二名","examples":[{"en":"Our team came second in the championship final.","zh":"我們隊在錦標賽決賽中得第二名。"},{"en":"To come second means to finish in second place.","zh":"得第二名，意思是以第二位完成比賽。"},{"en":"A runner may come second and still set a personal best.","zh":"跑手可能得第二名，但仍創下個人最佳成績。"},{"en":"Coming second can hurt when the team worked hard for first place.","zh":"當隊伍為第一名努力很久，得第二名可能令人難受。"},{"en":"The team came second, but the experience became a foundation for the future.","zh":"隊伍得第二名，但這次經驗成為未來的基礎。"}],"source":"2022 Q4.pdf","sourcePage":2},{"front":"make us consider","meaning":"令我們思考","examples":[{"en":"That result made us consider how to remember the season.","zh":"那個結果令我們思考如何記住這個賽季。"},{"en":"Make us consider means cause us to think carefully about something.","zh":"令我們思考，意思是使我們仔細考慮某事。"},{"en":"A close defeat may make players consider how they can improve.","zh":"一場接近的敗仗可能令球員思考如何進步。"},{"en":"Difficult results make teams consider what truly matters.","zh":"困難結果會令隊伍思考真正重要的是甚麼。"},{"en":"Second place made the team consider the season as growth, not failure.","zh":"第二名令隊伍思考把賽季看成成長，而不是失敗。"}],"source":"2022 Q4.pdf","sourcePage":2},{"front":"remember this season","meaning":"記住這個賽季","examples":[{"en":"We should remember this season as a foundation.","zh":"我們應把這個賽季記住為一個基礎。"},{"en":"To remember this season means to look back on the whole period of games, training, and growth.","zh":"記住這個賽季，意思是回顧整段比賽、訓練和成長時期。"},{"en":"Players may remember this season for the friendships they built.","zh":"球員可能因建立的友誼而記住這個賽季。"},{"en":"How a team remembers a season affects how it prepares next year.","zh":"隊伍如何記住一個賽季，會影響它下一年如何準備。"},{"en":"The speaker wants the team to remember this season with pride and purpose.","zh":"講者希望隊伍帶着自豪和目標記住這個賽季。"}],"source":"2022 Q4.pdf","sourcePage":2},{"front":"not as a defeat, but as a foundation","meaning":"不是失敗，而是基礎","examples":[{"en":"We should remember this season not as a defeat, but as a foundation.","zh":"我們應把這個賽季記住為不是失敗，而是基礎。"},{"en":"Not as a defeat, but as a foundation means the season should be seen as a starting point for future growth, not only a loss.","zh":"不是失敗，而是基礎，意思是這個賽季應被看成未來成長的起點，而不只是落敗。"},{"en":"A failed exam can be remembered not as shame, but as a foundation for better study habits.","zh":"一次考試失利可以被記住為不是羞恥，而是改善學習習慣的基礎。"},{"en":"This structure changes a negative result into a useful lesson.","zh":"這個結構把負面結果轉化為有用課題。"},{"en":"The team uses second place as a foundation for becoming stronger.","zh":"隊伍把第二名用作變得更強的基礎。"}],"source":"2022 Q4.pdf","sourcePage":2},{"front":"a foundation from which","meaning":"一個讓我們從中成長的基礎","examples":[{"en":"This season is a foundation from which we can grow stronger.","zh":"這個賽季是一個讓我們從中變得更強的基礎。"},{"en":"A foundation from which means a base that allows future progress to begin.","zh":"一個讓我們從中成長的基礎，意思是讓未來進步開始的根基。"},{"en":"Basic grammar is a foundation from which students can write better essays.","zh":"基本文法是學生可以從中寫出更好文章的基礎。"},{"en":"A difficult season can become a foundation if the team learns from it.","zh":"如果隊伍從中學習，困難賽季可以成為基礎。"},{"en":"The team sees this season as a foundation from which its next comeback can grow.","zh":"隊伍把這個賽季看成一個讓下一次捲土重來成長的基礎。"}],"source":"2022 Q4.pdf","sourcePage":2},{"front":"grow stronger, braver and more united","meaning":"變得更強、更勇敢、更團結","examples":[{"en":"This experience helped us grow stronger, braver and more united.","zh":"這次經驗幫助我們變得更強、更勇敢、更團結。"},{"en":"To grow stronger, braver and more united means to develop more ability, courage, and team spirit.","zh":"變得更強、更勇敢、更團結，意思是發展出更多能力、勇氣和團隊精神。"},{"en":"A class can grow stronger and more united after completing a difficult project together.","zh":"一個班級一起完成困難專題後，可以變得更強和更團結。"},{"en":"Challenges help teams grow when members support one another instead of blaming one another.","zh":"當成員互相支持而不是互相責怪，挑戰會幫助隊伍成長。"},{"en":"The season helped the players grow not only as athletes, but also as people.","zh":"這個賽季幫助球員不只作為運動員成長，也作為人而成長。"}],"source":"2022 Q4.pdf","sourcePage":2},{"front":"my message tonight is simple","meaning":"我今晚的信息很簡單","examples":[{"en":"My message tonight is simple: silver is not the end.","zh":"我今晚的信息很簡單：銀牌不是終點。"},{"en":"My message tonight is simple means the speaker wants to express one clear main idea.","zh":"我今晚的信息很簡單，意思是講者想表達一個清晰主要想法。"},{"en":"At a graduation dinner, a captain may say, “My message tonight is simple: keep believing.”","zh":"在畢業晚宴上，隊長可能說：「我今晚的信息很簡單：繼續相信。」"},{"en":"A simple message can be powerful when emotions are strong.","zh":"當情緒強烈時，簡單信息可以很有力量。"},{"en":"The speaker’s message is that second place should lead to future effort.","zh":"講者的信息是第二名應引向未來努力。"}],"source":"2022 Q4.pdf","sourcePage":2},{"front":"bring home silver","meaning":"奪得銀牌","examples":[{"en":"We may have brought home silver, but we gained something greater.","zh":"我們也許奪得銀牌，但我們得到更偉大的東西。"},{"en":"To bring home silver means to win second place and take back a silver medal.","zh":"奪得銀牌，意思是取得第二名並帶回銀牌。"},{"en":"The swimming team brought home silver after a close relay race.","zh":"游泳隊在接近的接力賽後奪得銀牌。"},{"en":"Bringing home silver can be disappointing if the team hoped for gold, but it is still an achievement.","zh":"如果隊伍希望奪金，奪得銀牌可能令人失望，但它仍是成就。"},{"en":"The speaker says silver matters, but character matters even more.","zh":"講者說銀牌重要，但品格更重要。"}],"source":"2022 Q4.pdf","sourcePage":2},{"front":"far more valuable than","meaning":"比……更有價值","examples":[{"en":"We discovered something far more valuable than a medal.","zh":"我們發現了比獎牌更有價值的東西。"},{"en":"Far more valuable than means much more important or meaningful than something else.","zh":"比某事更有價值，意思是比另一事物更重要或更有意義。"},{"en":"A student may gain confidence far more valuable than a prize.","zh":"學生可能獲得比獎項更有價值的信心。"},{"en":"Some experiences are far more valuable than awards because they change people deeply.","zh":"有些經驗比獎項更有價值，因為它們深深改變人。"},{"en":"The team discovered trust and discipline, which were far more valuable than silver.","zh":"隊伍發現了信任和紀律，它們比銀牌更有價值。"}],"source":"2022 Q4.pdf","sourcePage":2},{"front":"the character of this team","meaning":"這支隊伍的品格","examples":[{"en":"This season revealed the character of this team.","zh":"這個賽季展現了這支隊伍的品格。"},{"en":"The character of this team means the values, attitude, and spirit shown by the players together.","zh":"這支隊伍的品格，是球員共同展現的價值觀、態度和精神。"},{"en":"A team’s character appears when it keeps working after losing a match.","zh":"當隊伍落敗後仍繼續努力，隊伍品格就會出現。"},{"en":"Pressure reveals character because players must decide whether to give up or fight on.","zh":"壓力會顯示品格，因為球員必須決定放棄還是繼續奮戰。"},{"en":"This team’s character was shown through discipline, trust, and unity.","zh":"這支隊伍的品格透過紀律、信任和團結展現出來。"}],"source":"2022 Q4.pdf","sourcePage":2},{"front":"allow excuses to be louder than effort","meaning":"讓藉口蓋過努力","examples":[{"en":"Our coach never allowed our excuses to be louder than our effort.","zh":"我們的教練從不讓我們的藉口蓋過努力。"},{"en":"To allow excuses to be louder than effort means to let complaints matter more than hard work.","zh":"讓藉口蓋過努力，意思是讓投訴或理由比辛勤工作更重要。"},{"en":"A good teacher does not allow excuses to be louder than honest practice.","zh":"好老師不會讓藉口蓋過誠實練習。"},{"en":"Excuses become harmful when they drown out action.","zh":"當藉口淹沒行動，它們就變得有害。"},{"en":"The coach pushed the team to work instead of hiding behind reasons.","zh":"教練推動隊伍努力，而不是躲在理由後面。"}],"source":"2022 Q4.pdf","sourcePage":3},{"front":"teacher advisers","meaning":"負責老師","examples":[{"en":"Our teacher advisers handled schedules and small problems.","zh":"我們的負責老師處理時間表和小問題。"},{"en":"Teacher advisers are teachers who guide and support a student team or club.","zh":"負責老師，是指導和支援學生隊伍或學會的老師。"},{"en":"Teacher advisers may book courts, contact parents, and help players manage schoolwork.","zh":"負責老師可能預訂球場、聯絡家長，並幫助球員處理學業。"},{"en":"Good teacher advisers make student activities safer and more organised.","zh":"好的負責老師令學生活動更安全和更有組織。"},{"en":"The team thanked its teacher advisers for helping behind the scenes.","zh":"隊伍感謝負責老師在幕後幫忙。"}],"source":"2022 Q4.pdf","sourcePage":3},{"front":"training schedules","meaning":"訓練時間表","examples":[{"en":"The teacher advisers handled our training schedules.","zh":"負責老師處理我們的訓練時間表。"},{"en":"Training schedules are plans showing when and where practice sessions happen.","zh":"訓練時間表，是顯示練習何時何地進行的計劃。"},{"en":"A basketball team needs training schedules so players can balance practice and homework.","zh":"籃球隊需要訓練時間表，好讓球員平衡練習和功課。"},{"en":"Clear schedules reduce confusion and help players arrive prepared.","zh":"清晰時間表減少混亂，並幫助球員準備好到達。"},{"en":"The teacher advisers managed training schedules so the team could focus on improvement.","zh":"負責老師管理訓練時間表，讓隊伍可以專注進步。"}],"source":"2022 Q4.pdf","sourcePage":3},{"front":"countless small problems","meaning":"無數小問題","examples":[{"en":"Our teachers handled countless small problems for the team.","zh":"老師為隊伍處理無數小問題。"},{"en":"Countless small problems means many minor issues, too many to count easily.","zh":"無數小問題，意思是很多細小問題，多到難以逐一計算。"},{"en":"A team trip can involve countless small problems, such as late forms and missing socks.","zh":"球隊出行可能涉及無數小問題，例如遲交表格和遺失襪子。"},{"en":"Small problems matter because they can distract players if no one handles them.","zh":"小問題重要，因為如果沒有人處理，它們會令球員分心。"},{"en":"The teachers solved countless small problems so the season could continue smoothly.","zh":"老師解決無數小問題，讓賽季能順利繼續。"}],"source":"2022 Q4.pdf","sourcePage":3},{"front":"wait outside gyms","meaning":"在體育館外等候","examples":[{"en":"Our parents waited outside gyms after training.","zh":"訓練後，我們的父母在體育館外等候。"},{"en":"To wait outside gyms means to stay near sports halls while players finish practice.","zh":"在體育館外等候，意思是在運動場館附近等待球員完成練習。"},{"en":"Parents may wait outside gyms late at night after school training.","zh":"家長可能在學校訓練後深夜於體育館外等候。"},{"en":"Waiting outside gyms shows quiet support that players may not always notice.","zh":"在體育館外等候顯示默默支持，球員未必總是注意到。"},{"en":"The team thanked parents who waited patiently after long practices.","zh":"隊伍感謝長時間練習後耐心等候的父母。"}],"source":"2022 Q4.pdf","sourcePage":3},{"front":"prepare late dinners","meaning":"準備很晚的晚飯","examples":[{"en":"Our parents prepared late dinners after our training sessions.","zh":"我們的父母在訓練後準備很晚的晚飯。"},{"en":"To prepare late dinners means to cook or arrange meals at a later time than usual.","zh":"準備很晚的晚飯，意思是在比平常較晚的時間煮飯或安排飯餐。"},{"en":"A parent may prepare a late dinner when a student returns from evening practice.","zh":"當學生晚上練習後回家，家長可能準備很晚的晚飯。"},{"en":"Late dinners show family support behind a player’s effort.","zh":"很晚的晚飯顯示球員努力背後的家庭支持。"},{"en":"The team remembered that success depended on sacrifices at home too.","zh":"隊伍記得成功也依靠家中的犧牲。"}],"source":"2022 Q4.pdf","sourcePage":3},{"front":"written across our exhausted faces","meaning":"寫在我們疲憊的臉上","examples":[{"en":"The answer was written across our exhausted faces.","zh":"答案寫在我們疲憊的臉上。"},{"en":"Written across our exhausted faces means our tired expressions clearly showed the answer.","zh":"寫在我們疲憊的臉上，意思是我們疲倦的表情清楚顯示答案。"},{"en":"After the race, effort was written across the runners’ exhausted faces.","zh":"賽跑後，努力寫在跑手疲憊的臉上。"},{"en":"Faces can reveal truth when words are too difficult.","zh":"當文字太難說出口，臉孔可以顯示真相。"},{"en":"The team’s exhausted faces showed how much they had given.","zh":"隊伍疲憊的臉顯示他們付出了多少。"}],"source":"2022 Q4.pdf","sourcePage":3},{"front":"most of all","meaning":"最重要的是","examples":[{"en":"Most of all, I want to thank every teammate here.","zh":"最重要的是，我想感謝在場每一位隊友。"},{"en":"Most of all introduces the most important point among several points.","zh":"最重要的是，用來引出多個重點中最重要的一點。"},{"en":"The captain thanked the coach, parents, and, most of all, the teammates.","zh":"隊長感謝教練、家長，最重要的是感謝隊友。"},{"en":"Writers use this phrase when they want one idea to stand above the rest.","zh":"作者使用這個短語，是為了讓一個想法高於其他內容。"},{"en":"The speaker says teammates matter most because they carried the season together.","zh":"講者說隊友最重要，因為他們一起承擔這個賽季。"}],"source":"2022 Q4.pdf","sourcePage":3},{"front":"every teammate sitting here","meaning":"在座每一位隊友","examples":[{"en":"Every teammate sitting here carried part of this season.","zh":"在座每一位隊友都承擔了這個賽季的一部分。"},{"en":"Every teammate sitting here means each team member present at the dinner.","zh":"在座每一位隊友，意思是在晚宴現場的每一名隊員。"},{"en":"Every teammate sitting here has a different memory of training and matches.","zh":"在座每一位隊友對訓練和比賽都有不同記憶。"},{"en":"A team becomes strong when every teammate feels included and valued.","zh":"當每位隊友都感到被包括和被重視，隊伍就會強大。"},{"en":"The captain thanked every teammate sitting here because no role was too small.","zh":"隊長感謝在座每一位隊友，因為沒有任何角色太小。"}],"source":"2022 Q4.pdf","sourcePage":3},{"front":"starting five","meaning":"正選五人","examples":[{"en":"From our starting five to the bench players, everyone contributed.","zh":"從我們的正選五人到後備球員，每個人都有貢獻。"},{"en":"The starting five are the five basketball players who begin the game on court.","zh":"正選五人，是籃球比賽開始時在場上的五名球員。"},{"en":"The starting five set the early pace of the match.","zh":"正選五人定下比賽早段的節奏。"},{"en":"A strong starting five matters, but a team also needs support from substitutes.","zh":"強大的正選五人很重要，但隊伍也需要後備支援。"},{"en":"The speaker praises both the starting five and the bench because everyone helped.","zh":"講者讚揚正選五人和後備球員，因為每個人都有幫助。"}],"source":"2022 Q4.pdf","sourcePage":3},{"front":"come off the bench","meaning":"後備上陣","examples":[{"en":"Some players came off the bench and changed the game.","zh":"有些球員後備上陣並改變了比賽。"},{"en":"To come off the bench means to enter a match as a substitute after not starting.","zh":"後備上陣，意思是沒有正選開始，但作為替補進入比賽。"},{"en":"A player may come off the bench in the second quarter and score important points.","zh":"球員可能在第二節後備上陣並取得重要分數。"},{"en":"Bench players can change a game through energy, defence, and focus.","zh":"後備球員可以透過活力、防守和專注改變比賽。"},{"en":"The team valued players who came off the bench because they stayed ready.","zh":"隊伍重視後備上陣的球員，因為他們一直準備好。"}],"source":"2022 Q4.pdf","sourcePage":4},{"front":"carry part of this season","meaning":"承擔這個賽季的一部分","examples":[{"en":"Each teammate carried part of this season.","zh":"每位隊友都承擔了這個賽季的一部分。"},{"en":"To carry part of this season means to contribute to the team’s journey in one’s own way.","zh":"承擔這個賽季的一部分，意思是以自己的方式為隊伍旅程作出貢獻。"},{"en":"A quiet player may carry part of the season by encouraging others during training.","zh":"安靜球員可能透過在訓練中鼓勵別人，承擔賽季的一部分。"},{"en":"A season is shared when everyone carries responsibility, memory, and effort.","zh":"當每個人都承擔責任、記憶和努力，賽季就是共同擁有的。"},{"en":"The captain reminds the team that each person helped build the season.","zh":"隊長提醒隊伍，每個人都幫助建立這個賽季。"}],"source":"2022 Q4.pdf","sourcePage":4},{"front":"no one wins alone","meaning":"沒有人能獨自勝利","examples":[{"en":"No one wins alone in a true team.","zh":"在真正的隊伍中，沒有人能獨自勝利。"},{"en":"No one wins alone means success depends on support from others.","zh":"沒有人能獨自勝利，意思是成功依靠別人的支持。"},{"en":"A striker may score, but teammates pass, defend, and create chances.","zh":"前鋒可能入球，但隊友傳球、防守和創造機會。"},{"en":"Team success requires shared effort, not only one person’s talent.","zh":"團隊成功需要共同努力，而不只是一個人的天分。"},{"en":"The speaker says every victory belongs to the whole team.","zh":"講者說每場勝利都屬於整支隊伍。"}],"source":"2022 Q4.pdf","sourcePage":4},{"front":"no one loses alone","meaning":"沒有人獨自落敗","examples":[{"en":"No one loses alone when the team stands together.","zh":"當隊伍並肩而立，沒有人獨自落敗。"},{"en":"No one loses alone means defeat is shared by the team, not carried by one person only.","zh":"沒有人獨自落敗，意思是失敗由隊伍共同承擔，而不是只由一個人承受。"},{"en":"A player who misses a shot should not feel that the loss belongs only to them.","zh":"錯失一球的球員不應覺得落敗只屬於自己。"},{"en":"Sharing defeat helps teammates support one another instead of blaming one another.","zh":"共同承擔失敗幫助隊友互相支持，而不是互相責怪。"},{"en":"The captain reminds players that they faced the final together.","zh":"隊長提醒球員，他們是一起面對決賽的。"}],"source":"2022 Q4.pdf","sourcePage":4},{"front":"no one grows alone","meaning":"沒有人獨自成長","examples":[{"en":"No one grows alone in a united team.","zh":"在團結的隊伍中，沒有人獨自成長。"},{"en":"No one grows alone means personal improvement happens through shared support and challenge.","zh":"沒有人獨自成長，意思是個人成長來自共同支持和挑戰。"},{"en":"A beginner improves faster when teammates practise with them patiently.","zh":"當隊友耐心陪伴練習，初學者會進步得更快。"},{"en":"Growth in a team comes from feedback, trust, and common effort.","zh":"團隊中的成長來自回饋、信任和共同努力。"},{"en":"The speaker believes each player’s growth was connected to the whole team.","zh":"講者相信每名球員的成長都與整支隊伍相連。"}],"source":"2022 Q4.pdf","sourcePage":4},{"front":"look back","meaning":"回望","examples":[{"en":"When we look back, we should remember the road that brought us there.","zh":"當我們回望時，應記得帶我們走到那裏的路。"},{"en":"To look back means to think about past events after they have happened.","zh":"回望，意思是在事情發生後思考過去。"},{"en":"Players may look back on a season and notice lessons they missed at the time.","zh":"球員可能回望一個賽季，注意到當時錯過的課題。"},{"en":"Looking back helps people turn pain into understanding.","zh":"回望幫助人們把痛苦變成理解。"},{"en":"The team looks back not only at the final, but also at the months of work before it.","zh":"隊伍回望的不只是決賽，還有之前數月的努力。"}],"source":"2022 Q4.pdf","sourcePage":4},{"front":"not only…, but also…","meaning":"不但……而且……","examples":[{"en":"We should remember not only the final match, but also the road to it.","zh":"我們應記住不但決賽，而且通往決賽的路。"},{"en":"Not only…, but also… shows that two things are important, not just one.","zh":"不但……而且……，顯示兩件事都重要，而不只是一件。"},{"en":"Students should value not only marks, but also the effort behind them.","zh":"學生應重視不但分數，而且背後的努力。"},{"en":"This structure helps writers add a second, often deeper, point.","zh":"這個結構幫助作者加入第二個，通常更深入的重點。"},{"en":"The speaker wants the team to remember both the final and the journey.","zh":"講者希望隊伍同時記住決賽和整段旅程。"}],"source":"2022 Q4.pdf","sourcePage":4},{"front":"final match","meaning":"決賽","examples":[{"en":"The final match was only one part of the season.","zh":"決賽只是這個賽季的一部分。"},{"en":"The final match is the last and deciding game in a competition.","zh":"決賽，是比賽中最後和決定性的賽事。"},{"en":"A team may feel nervous before the final match because the title is close.","zh":"隊伍在決賽前可能緊張，因為冠軍近在眼前。"},{"en":"A final match matters, but it does not contain every lesson from the season.","zh":"決賽重要，但它不包含賽季中的每個課題。"},{"en":"The speaker says the final match should be remembered alongside all the training.","zh":"講者說決賽應與所有訓練一起被記住。"}],"source":"2022 Q4.pdf","sourcePage":4},{"front":"the road that brought us there","meaning":"帶我們走到那裏的路","examples":[{"en":"We should remember the road that brought us to the final.","zh":"我們應記住帶我們走到決賽的路。"},{"en":"The road that brought us there means the long process, effort, and experiences that led to that moment.","zh":"帶我們走到那裏的路，意思是引領到那一刻的長過程、努力和經歷。"},{"en":"A school play’s success includes the road that brought students to opening night.","zh":"學校戲劇的成功包括帶學生走到首演夜的道路。"},{"en":"The journey matters because it shapes the people who reach the destination.","zh":"旅程重要，因為它塑造到達目的地的人。"},{"en":"The team’s road included training, setbacks, injuries, and shared belief.","zh":"隊伍的道路包括訓練、挫折、受傷和共同信念。"}],"source":"2022 Q4.pdf","sourcePage":4},{"front":"morning training","meaning":"早上訓練","examples":[{"en":"We remember morning training when the campus was still half asleep.","zh":"我們記得校園仍半睡半醒時的早上訓練。"},{"en":"Morning training is practice held early in the day, often before lessons begin.","zh":"早上訓練，是在一天較早時間，通常上課前進行的練習。"},{"en":"Players may arrive for morning training before most students reach school.","zh":"球員可能在大多數學生到校前已到達早上訓練。"},{"en":"Morning training builds discipline because it requires effort before the day starts.","zh":"早上訓練建立紀律，因為它要求人在一天開始前努力。"},{"en":"The team remembers morning training as proof of its commitment.","zh":"隊伍把早上訓練記作承諾的證明。"}],"source":"2022 Q4.pdf","sourcePage":4},{"front":"the campus was still half asleep","meaning":"校園仍半睡半醒","examples":[{"en":"Morning training began when the campus was still half asleep.","zh":"早上訓練在校園仍半睡半醒時開始。"},{"en":"The campus was still half asleep means the school was quiet and not fully active yet.","zh":"校園仍半睡半醒，意思是學校仍很安靜，尚未完全活躍起來。"},{"en":"At seven o’clock, the campus was still half asleep, with only cleaners and athletes moving.","zh":"早上七時，校園仍半睡半醒，只有清潔工和運動員在走動。"},{"en":"Early training feels special because the school is calm before the rush begins.","zh":"早訓很特別，因為在繁忙開始前，學校很平靜。"},{"en":"The phrase shows how early and disciplined the team’s practice was.","zh":"這個短語顯示隊伍練習有多早和多有紀律。"}],"source":"2022 Q4.pdf","sourcePage":5},{"front":"missed lay-ups","meaning":"失手上籃","examples":[{"en":"We remember missed lay-ups during training.","zh":"我們記得訓練中的失手上籃。"},{"en":"Missed lay-ups are close-range basketball shots that players fail to score.","zh":"失手上籃，是球員未能投進近距離上籃。"},{"en":"A player may miss lay-ups when tired or under pressure.","zh":"球員疲倦或受壓時可能失手上籃。"},{"en":"Missed lay-ups are frustrating, but they show where practice is needed.","zh":"失手上籃令人挫敗，但它顯示哪裏需要練習。"},{"en":"The team remembers missed lay-ups because mistakes were part of improvement.","zh":"隊伍記得失手上籃，因為錯誤是進步的一部分。"}],"source":"2022 Q4.pdf","sourcePage":5},{"front":"repeated sprints","meaning":"反覆衝刺","examples":[{"en":"Repeated sprints helped build our stamina.","zh":"反覆衝刺幫助我們建立耐力。"},{"en":"Repeated sprints are short fast runs done again and again during training.","zh":"反覆衝刺，是在訓練中一次又一次進行的短距離快跑。"},{"en":"Basketball players do repeated sprints to practise quick attacks and defence.","zh":"籃球員做反覆衝刺，以練習快速進攻和防守。"},{"en":"Repeated sprints are tiring, but they build endurance for late-game pressure.","zh":"反覆衝刺很累，但它建立面對比賽後段壓力的耐力。"},{"en":"The team hated the sprints at times, but they made the players stronger.","zh":"隊伍有時討厭衝刺，但它令球員更強。"}],"source":"2022 Q4.pdf","sourcePage":5},{"front":"twisted ankles","meaning":"扭傷腳踝","examples":[{"en":"Some players trained through twisted ankles.","zh":"有些球員在扭傷腳踝中仍繼續訓練。"},{"en":"Twisted ankles are ankle injuries caused by the foot turning awkwardly.","zh":"扭傷腳踝，是腳不自然扭動造成的腳踝傷患。"},{"en":"A player may get a twisted ankle after landing badly from a jump.","zh":"球員跳起落地不佳後可能扭傷腳踝。"},{"en":"Twisted ankles can slow a team down because movement becomes painful.","zh":"扭傷腳踝會拖慢隊伍，因為移動變得痛楚。"},{"en":"The mention of twisted ankles shows the physical cost of the season.","zh":"提到扭傷腳踝，顯示這個賽季的身體代價。"}],"source":"2022 Q4.pdf","sourcePage":5},{"front":"silent bus rides","meaning":"沉默的巴士旅程","examples":[{"en":"We remember silent bus rides after difficult games.","zh":"我們記得艱難比賽後沉默的巴士旅程。"},{"en":"Silent bus rides are quiet journeys when players are too tired or disappointed to talk.","zh":"沉默的巴士旅程，是球員太疲倦或失望而不說話的車程。"},{"en":"After a heavy loss, the team sat through a silent bus ride back to school.","zh":"大敗後，隊伍坐着沉默的巴士旅程回校。"},{"en":"Silence after a match can show reflection, sadness, or shared exhaustion.","zh":"比賽後的沉默可以顯示反思、傷心或共同疲憊。"},{"en":"The silent bus rides became part of the team’s memory.","zh":"沉默的巴士旅程成為隊伍記憶的一部分。"}],"source":"2022 Q4.pdf","sourcePage":5},{"front":"old jerseys","meaning":"舊球衣","examples":[{"en":"The smell of sweat stayed on our old jerseys.","zh":"汗味留在我們的舊球衣上。"},{"en":"Old jerseys are team shirts that have been worn through many practices and games.","zh":"舊球衣，是在許多練習和比賽中穿過的隊服。"},{"en":"Old jerseys may look faded but carry strong memories.","zh":"舊球衣可能看起來褪色，但承載強烈記憶。"},{"en":"Sports clothing can remind players of effort because it holds marks of training.","zh":"運動衣物可以提醒球員努力，因為它留下訓練痕跡。"},{"en":"The old jerseys symbolise the hard work the team shared.","zh":"舊球衣象徵隊伍共同付出的辛勞。"}],"source":"2022 Q4.pdf","sourcePage":5},{"front":"be behind by ten points","meaning":"落後十分","examples":[{"en":"We were behind by ten points but refused to give up.","zh":"我們落後十分，但拒絕放棄。"},{"en":"To be behind by ten points means to have ten fewer points than the other team.","zh":"落後十分，意思是比對方少十分。"},{"en":"A basketball team behind by ten points must stay calm and defend well.","zh":"落後十分的籃球隊必須保持冷靜並做好防守。"},{"en":"Being behind tests a team’s belief because the game feels harder.","zh":"落後會考驗隊伍信念，因為比賽感覺更困難。"},{"en":"The team learned resilience by fighting back from ten points down.","zh":"隊伍透過從落後十分中追回，學會韌性。"}],"source":"2022 Q4.pdf","sourcePage":5},{"front":"refuse to fold","meaning":"拒絕崩潰；拒絕放棄","examples":[{"en":"Even when we were behind, we refused to fold.","zh":"即使落後，我們仍拒絕崩潰。"},{"en":"To refuse to fold means to refuse to collapse, quit, or lose courage under pressure.","zh":"拒絕崩潰或拒絕放棄，意思是在壓力下不倒下、不退出、不失去勇氣。"},{"en":"A team refuses to fold when it keeps defending after losing the lead.","zh":"當隊伍失去領先後仍繼續防守，就是拒絕放棄。"},{"en":"Refusing to fold shows mental strength more than comfort.","zh":"拒絕崩潰顯示的是心理力量，而不是舒適。"},{"en":"The players refused to fold because they trusted one another.","zh":"球員拒絕放棄，因為他們信任彼此。"}],"source":"2022 Q4.pdf","sourcePage":5},{"front":"the semi-final","meaning":"準決賽","examples":[{"en":"We remember the semi-final when our defence finally clicked.","zh":"我們記得準決賽，那時我們的防守終於配合起來。"},{"en":"The semi-final is the match before the final, where winners move on to compete for the championship.","zh":"準決賽，是決賽前的比賽，勝方會晉級爭奪冠軍。"},{"en":"A team may feel great pressure in the semi-final because the final is so close.","zh":"隊伍在準決賽中可能感到很大壓力，因為決賽近在眼前。"},{"en":"Winning a semi-final can prove that a team is ready for the highest stage.","zh":"贏得準決賽可以證明隊伍準備好登上最高舞台。"},{"en":"The team remembers the semi-final as the moment its defence came together.","zh":"隊伍把準決賽記作防守終於融合的一刻。"}],"source":"2022 Q4.pdf","sourcePage":5},{"front":"defence finally clicked","meaning":"防守終於配合起來","examples":[{"en":"In the semi-final, our defence finally clicked.","zh":"在準決賽中，我們的防守終於配合起來。"},{"en":"Defence finally clicked means the team’s defensive actions started working smoothly together.","zh":"防守終於配合起來，意思是隊伍的防守動作開始順暢合作。"},{"en":"A football team’s defence clicks when players cover each other without hesitation.","zh":"當足球隊球員毫不猶豫互相補位，防守就配合起來。"},{"en":"Defence clicks after trust and practice become automatic.","zh":"防守在信任和練習變成自然反應後會配合起來。"},{"en":"The semi-final showed that the team’s defensive training had paid off.","zh":"準決賽顯示隊伍的防守訓練有成果。"}],"source":"2022 Q4.pdf","sourcePage":5},{"front":"like a lock closing","meaning":"像鎖扣上一樣","examples":[{"en":"Our defence clicked like a lock closing.","zh":"我們的防守像鎖扣上一樣配合。"},{"en":"Like a lock closing means something worked tightly, securely, and exactly in place.","zh":"像鎖扣上一樣，意思是某事緊密、安全並準確到位地運作。"},{"en":"The class performance came together like a lock closing after weeks of rehearsal.","zh":"經過數星期排練後，班級表演像鎖扣上一樣融合。"},{"en":"This image suggests precision, teamwork, and firmness.","zh":"這個畫面暗示精準、團隊合作和穩固。"},{"en":"The defence felt like a lock closing because every player covered the right space.","zh":"防守感覺像鎖扣上一樣，因為每名球員都補上正確位置。"}],"source":"2022 Q4.pdf","sourcePage":6},{"front":"not glamorous","meaning":"不光鮮","examples":[{"en":"These moments were not glamorous, but they built us.","zh":"這些時刻並不光鮮，但它們塑造了我們。"},{"en":"Not glamorous means not exciting, beautiful, or impressive on the surface.","zh":"不光鮮，意思是表面上不刺激、不漂亮或不令人矚目。"},{"en":"Repeating basic drills is not glamorous, but it improves skill.","zh":"反覆做基本訓練不光鮮，但能改善技巧。"},{"en":"Many important parts of success are not glamorous because they happen quietly.","zh":"成功中很多重要部分並不光鮮，因為它們默默發生。"},{"en":"The team was built by unglamorous work such as sprints, mistakes, and training.","zh":"隊伍由不光鮮的工作塑造，例如衝刺、錯誤和訓練。"}],"source":"2022 Q4.pdf","sourcePage":6},{"front":"build us","meaning":"塑造了我們","examples":[{"en":"The difficult moments built us as a team.","zh":"艱難時刻把我們塑造成一支隊伍。"},{"en":"To build us means to shape our character, strength, and unity over time.","zh":"塑造了我們，意思是隨時間形成我們的品格、力量和團結。"},{"en":"Hard training can build a team by teaching trust and patience.","zh":"艱苦訓練可以透過教導信任和耐性來塑造隊伍。"},{"en":"Difficulties build people when they respond with effort instead of excuses.","zh":"當人們以努力而非藉口回應困難，困難就會塑造他們。"},{"en":"The season built the team through pressure, failure, and shared discipline.","zh":"這個賽季透過壓力、失敗和共同紀律塑造了隊伍。"}],"source":"2022 Q4.pdf","sourcePage":6},{"front":"the last page of a book","meaning":"一本書的最後一頁","examples":[{"en":"The final was only the last page of a book we had written together.","zh":"決賽只是我們一起寫下的一本書的最後一頁。"},{"en":"The last page of a book means the ending of a longer story or journey.","zh":"一本書的最後一頁，意思是較長故事或旅程的結尾。"},{"en":"A graduation ceremony may feel like the last page of a school book.","zh":"畢業典禮可能感覺像校園之書的最後一頁。"},{"en":"The final page matters, but it only makes sense because of all the pages before it.","zh":"最後一頁重要，但它因前面所有頁面才有意義。"},{"en":"The speaker says the final was not the whole story, only its last page.","zh":"講者說決賽不是整個故事，只是最後一頁。"}],"source":"2022 Q4.pdf","sourcePage":6},{"front":"write together for months","meaning":"一起寫下好幾個月","examples":[{"en":"We had been writing this season together for months.","zh":"我們已一起寫下這個賽季好幾個月。"},{"en":"To write together for months means to build a shared story through long effort and experience.","zh":"一起寫下好幾個月，意思是透過長時間努力和經歷建立共同故事。"},{"en":"A drama group writes its year together through rehearsals, mistakes, and performances.","zh":"戲劇組透過排練、錯誤和演出一起寫下一年。"},{"en":"Teams create stories over time through repeated practice and common struggle.","zh":"隊伍透過反覆練習和共同掙扎，隨時間創造故事。"},{"en":"The players wrote the season together long before the final arrived.","zh":"在決賽到來很久之前，球員已一起寫下這個賽季。"}],"source":"2022 Q4.pdf","sourcePage":6},{"front":"coming second hurt","meaning":"得第二名令人難受","examples":[{"en":"Coming second hurt after such a close season.","zh":"在如此接近的賽季後，得第二名令人難受。"},{"en":"Coming second hurt means finishing in second place felt painful or disappointing.","zh":"得第二名令人難受，意思是以第二名完成讓人感到痛苦或失望。"},{"en":"A runner may feel that coming second hurts when first place was only one step away.","zh":"當第一名只差一步，跑手可能覺得得第二名令人難受。"},{"en":"Pain after second place shows how much the team cared.","zh":"第二名後的痛苦顯示隊伍有多在乎。"},{"en":"The speaker admits that coming second hurt instead of pretending it was easy.","zh":"講者承認得第二名令人難受，而不是假裝很容易接受。"}],"source":"2022 Q4.pdf","sourcePage":6},{"front":"dishonest to pretend otherwise","meaning":"假裝不是這樣是不誠實的","examples":[{"en":"It would be dishonest to pretend otherwise.","zh":"假裝不是這樣是不誠實的。"},{"en":"Dishonest to pretend otherwise means it would be false to act as if the feeling or fact were not true.","zh":"假裝不是這樣是不誠實的，意思是假裝某種感受或事實不是真的，是虛假的。"},{"en":"After a painful loss, it is dishonest to pretend nobody feels disappointed.","zh":"痛苦落敗後，假裝沒有人失望是不誠實的。"},{"en":"Honest reflection begins by admitting real emotions.","zh":"誠實反思始於承認真實情緒。"},{"en":"The captain says the team should admit that silver hurt.","zh":"隊長說隊伍應承認銀牌令人難受。"}],"source":"2022 Q4.pdf","sourcePage":6},{"front":"when the buzzer sounded","meaning":"當終場哨聲響起時","examples":[{"en":"When the buzzer sounded, some players stared at the floor.","zh":"當終場哨聲響起時，有些球員盯着地板。"},{"en":"When the buzzer sounded means when the signal marked the end of the game.","zh":"當終場哨聲響起時，意思是比賽結束的訊號出現時。"},{"en":"When the buzzer sounded, the crowd knew the final result.","zh":"當終場哨聲響起時，觀眾知道了最終結果。"},{"en":"The final buzzer can make joy or disappointment suddenly real.","zh":"終場哨聲可以令喜悅或失望突然變得真實。"},{"en":"For the team, the buzzer sounded like the end of a long journey.","zh":"對隊伍來說，終場哨聲像漫長旅程的結束。"}],"source":"2022 Q4.pdf","sourcePage":6},{"front":"stare at the floor","meaning":"盯着地板","examples":[{"en":"Some teammates stared at the floor after the match.","zh":"比賽後，有些隊友盯着地板。"},{"en":"To stare at the floor means to keep looking down, often because of sadness, shame, or deep thought.","zh":"盯着地板，意思是一直向下看，通常因悲傷、羞愧或深思。"},{"en":"A player may stare at the floor after missing an important shot.","zh":"球員錯失重要一球後可能盯着地板。"},{"en":"Looking down can show disappointment when words are hard to find.","zh":"當難以找到說話時，向下望可以顯示失望。"},{"en":"The teammates stared at the floor because the loss felt heavy.","zh":"隊友盯着地板，因為落敗感覺沉重。"}],"source":"2022 Q4.pdf","sourcePage":6},{"front":"bite their lips","meaning":"咬着嘴唇","examples":[{"en":"Some players were biting their lips, trying not to cry.","zh":"有些球員咬着嘴唇，試着忍住不哭。"},{"en":"To bite their lips means to press the lips with the teeth, often to control emotion.","zh":"咬着嘴唇，意思是用牙齒壓住嘴唇，通常是為了控制情緒。"},{"en":"A student may bite their lip while waiting for exam results.","zh":"學生等待考試結果時可能咬着嘴唇。"},{"en":"People bite their lips when they are holding back tears or words.","zh":"人們忍住眼淚或說話時會咬着嘴唇。"},{"en":"The players bit their lips because the final meant so much to them.","zh":"球員咬着嘴唇，因為決賽對他們意義重大。"}],"source":"2022 Q4.pdf","sourcePage":6},{"front":"try not to cry","meaning":"忍住不哭","examples":[{"en":"Some teammates tried not to cry after the final.","zh":"決賽後，有些隊友試着忍住不哭。"},{"en":"To try not to cry means to make an effort to hold back tears.","zh":"忍住不哭，意思是努力抑制眼淚。"},{"en":"A student may try not to cry after losing a close race.","zh":"學生在接近的賽跑落敗後可能忍住不哭。"},{"en":"Trying not to cry shows how strong the emotion is.","zh":"忍住不哭顯示情緒有多強烈。"},{"en":"The players tried not to cry because disappointment and pride came together.","zh":"球員忍住不哭，因為失望和自豪交織在一起。"}],"source":"2022 Q4.pdf","sourcePage":7},{"front":"as captain","meaning":"作為隊長","examples":[{"en":"As captain, I kept thinking about the mistakes I had made.","zh":"作為隊長，我一直想着自己犯過的錯誤。"},{"en":"As captain means in the role of team leader.","zh":"作為隊長，意思是以隊伍領袖的身份。"},{"en":"As captain, a player must encourage teammates even after defeat.","zh":"作為隊長，球員即使落敗後也必須鼓勵隊友。"},{"en":"Captains often feel responsible for both decisions and mistakes.","zh":"隊長常對決定和錯誤都感到有責任。"},{"en":"The speaker reflects as captain because leadership brings pressure.","zh":"講者作為隊長反思，因為領導帶來壓力。"}],"source":"2022 Q4.pdf","sourcePage":7},{"front":"the pass I should have made","meaning":"我本應傳出的一球","examples":[{"en":"I kept thinking about the pass I should have made earlier.","zh":"我一直想着自己早些時候本應傳出的一球。"},{"en":"The pass I should have made means a pass the speaker now believes would have been the better choice.","zh":"我本應傳出的一球，意思是講者現在認為當時更應該選擇的傳球。"},{"en":"A player may regret the pass they should have made when a teammate was open.","zh":"當隊友無人防守時，球員可能後悔本應傳出的一球。"},{"en":"Missed decisions can stay in a player’s mind after a close loss.","zh":"在接近的敗仗後，錯過的決定會留在球員腦中。"},{"en":"The captain remembers the pass as part of learning from the final.","zh":"隊長把那次傳球記作從決賽中學習的一部分。"}],"source":"2022 Q4.pdf","sourcePage":7},{"front":"the rebound I could have taken","meaning":"我本可以搶到的籃板","examples":[{"en":"I thought about the rebound I could have taken.","zh":"我想着自己本可以搶到的籃板。"},{"en":"The rebound I could have taken means the missed chance to catch the ball after a failed shot.","zh":"我本可以搶到的籃板，意思是投籃不中後本來有機會接到的球。"},{"en":"A player may remember a rebound they could have taken if they had moved faster.","zh":"如果球員移動更快，可能會記得自己本可以搶到的籃板。"},{"en":"Rebounds matter because they can give a team another chance to score.","zh":"籃板重要，因為它可以給隊伍另一個得分機會。"},{"en":"The captain thinks about the rebound not to blame himself, but to improve.","zh":"隊長思考那個籃板，不是為了責怪自己，而是為了進步。"}],"source":"2022 Q4.pdf","sourcePage":7},{"front":"sport teaches us a lesson","meaning":"運動教會我們一課","examples":[{"en":"Sport teaches us a lesson that classrooms sometimes cannot.","zh":"運動教會我們一課，是課室有時不能做到的。"},{"en":"Sport teaches us a lesson means sports give people important understanding through experience.","zh":"運動教會我們一課，意思是運動透過經驗給人重要理解。"},{"en":"A hard match can teach patience more strongly than a lecture.","zh":"一場艱難比賽可能比講課更有力地教會耐性。"},{"en":"Sport teaches lessons because players feel pressure, failure, teamwork, and recovery directly.","zh":"運動教會課題，因為球員直接感受壓力、失敗、團隊合作和恢復。"},{"en":"The team learned from sport that disappointment can still be meaningful.","zh":"隊伍從運動中學到，失望仍可以有意義。"}],"source":"2022 Q4.pdf","sourcePage":7},{"front":"classrooms sometimes cannot","meaning":"課室有時不能做到","examples":[{"en":"Sport can teach lessons that classrooms sometimes cannot.","zh":"運動可以教會課室有時不能做到的課題。"},{"en":"Classrooms sometimes cannot means ordinary lessons may not fully teach some experiences.","zh":"課室有時不能做到，意思是普通課堂未必能完全教會某些經驗。"},{"en":"Classrooms sometimes cannot teach how it feels to lose in front of a crowd.","zh":"課室有時不能教會在人群面前落敗是甚麼感覺。"},{"en":"Real experiences can make lessons deeper than explanations alone.","zh":"真實經驗可以令課題比單靠解釋更深入。"},{"en":"The final taught the players something classrooms sometimes cannot: how to stand after pain.","zh":"決賽教會球員課室有時不能做到的一點：痛苦後如何站起來。"}],"source":"2022 Q4.pdf","sourcePage":7},{"front":"the opposite of achievement","meaning":"成就的相反","examples":[{"en":"Disappointment is not the opposite of achievement.","zh":"失望不是成就的相反。"},{"en":"The opposite of achievement means something that seems completely against success.","zh":"成就的相反，意思是看似完全與成功相對的東西。"},{"en":"Failure is not always the opposite of achievement if it teaches useful lessons.","zh":"如果失敗教會有用課題，它不一定是成就的相反。"},{"en":"Disappointment may appear beside achievement when people care deeply.","zh":"當人們深深在乎，失望可能與成就並存。"},{"en":"The speaker says pain after silver does not cancel the team’s achievement.","zh":"講者說銀牌後的痛苦並不取消隊伍的成就。"}],"source":"2022 Q4.pdf","sourcePage":7},{"front":"proof that","meaning":"……的證明","examples":[{"en":"Disappointment is proof that we cared deeply.","zh":"失望是我們深深在乎的證明。"},{"en":"Proof that means evidence showing something is true.","zh":"……的證明，意思是顯示某事真實的證據。"},{"en":"A student’s nervousness before a performance is proof that the event matters to them.","zh":"學生在表演前緊張，是活動對他重要的證明。"},{"en":"Strong emotions can be proof that people gave real effort.","zh":"強烈情緒可以證明人們付出了真正努力。"},{"en":"The team’s disappointment proved that the final truly mattered.","zh":"隊伍的失望證明決賽真的很重要。"}],"source":"2022 Q4.pdf","sourcePage":7},{"front":"care enough to give everything","meaning":"在乎到願意付出一切","examples":[{"en":"We cared enough to give everything in the final.","zh":"我們在乎到願意在決賽中付出一切。"},{"en":"To care enough to give everything means to value something so much that one gives full effort.","zh":"在乎到願意付出一切，意思是非常重視某事，所以投入全部努力。"},{"en":"A runner who finishes despite pain cares enough to give everything.","zh":"跑手即使痛楚仍完成賽事，就是在乎到願意付出一切。"},{"en":"Giving everything can hurt, but it also shows commitment.","zh":"付出一切可能會痛，但也顯示承諾。"},{"en":"The team’s pain came from caring enough to give everything.","zh":"隊伍的痛苦來自在乎到願意付出一切。"}],"source":"2022 Q4.pdf","sourcePage":7},{"front":"not weakness","meaning":"不是軟弱","examples":[{"en":"The pain we felt was not weakness.","zh":"我們感受到的痛苦不是軟弱。"},{"en":"Not weakness means not a sign of being weak or lacking courage.","zh":"不是軟弱，意思是不是弱小或缺乏勇氣的表現。"},{"en":"Crying after a hard loss is not weakness if the tears come from effort.","zh":"艱難落敗後哭泣並不是軟弱，如果眼淚來自努力。"},{"en":"Feeling pain can show care rather than failure.","zh":"感到痛苦可以顯示在乎，而不是失敗。"},{"en":"The speaker tells the team that disappointment is not weakness but commitment.","zh":"講者告訴隊伍，失望不是軟弱，而是承諾。"}],"source":"2022 Q4.pdf","sourcePage":7},{"front":"on the contrary","meaning":"相反","examples":[{"en":"On the contrary, the pain showed our commitment.","zh":"相反，痛苦顯示了我們的承諾。"},{"en":"On the contrary means the opposite is true.","zh":"相反，意思是事實正好相反。"},{"en":"Some people think asking for help is weak; on the contrary, it can show maturity.","zh":"有些人以為求助是軟弱；相反，它可以顯示成熟。"},{"en":"This phrase corrects a mistaken idea strongly.","zh":"這個短語有力地糾正錯誤想法。"},{"en":"The speaker uses it to say pain is not weakness, but evidence of care.","zh":"講者用它來說明痛苦不是軟弱，而是在乎的證據。"}],"source":"2022 Q4.pdf","sourcePage":8},{"front":"commitment leaving a bruise","meaning":"承諾留下的瘀傷","examples":[{"en":"The pain was commitment leaving a bruise.","zh":"這份痛苦是承諾留下的瘀傷。"},{"en":"Commitment leaving a bruise means deep dedication can leave emotional pain after great effort.","zh":"承諾留下的瘀傷，意思是深切投入在巨大努力後留下情感痛楚。"},{"en":"A student’s sadness after losing a debate may be commitment leaving a bruise.","zh":"學生輸掉辯論後的傷心，可能是承諾留下的瘀傷。"},{"en":"Bruises show that something mattered enough to affect us.","zh":"瘀傷顯示某事重要到足以影響我們。"},{"en":"The phrase turns disappointment into a sign of serious effort.","zh":"這個短語把失望轉化為認真努力的標記。"}],"source":"2022 Q4.pdf","sourcePage":8},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, this season taught us what kind of team we are becoming.","zh":"更重要的是，這個賽季教會我們正在成為怎樣的隊伍。"},{"en":"More importantly introduces a point that matters even more than the previous one.","zh":"更重要的是，用來引出比前一點更重要的內容。"},{"en":"We won many games; more importantly, we learned to trust one another.","zh":"我們贏了很多比賽；更重要的是，我們學會信任彼此。"},{"en":"Writers use this phrase to move from result to deeper meaning.","zh":"作者使用這個短語，由結果轉向更深意義。"},{"en":"The speaker says the team’s growth matters more than the final score.","zh":"講者說隊伍的成長比最終比分更重要。"}],"source":"2022 Q4.pdf","sourcePage":8},{"front":"what kind of team we are becoming","meaning":"我們正在成為怎樣的隊伍","examples":[{"en":"This season showed us what kind of team we are becoming.","zh":"這個賽季向我們顯示，我們正在成為怎樣的隊伍。"},{"en":"What kind of team we are becoming means the identity, habits, and values the team is developing.","zh":"我們正在成為怎樣的隊伍，意思是隊伍正在形成的身份、習慣和價值觀。"},{"en":"A team becomes generous when players support the weakest member.","zh":"當球員支持最弱的成員，隊伍就變得寬厚。"},{"en":"Seasons reveal team identity through repeated choices under pressure.","zh":"賽季透過壓力下的重複選擇揭示隊伍身份。"},{"en":"The speaker believes the team is becoming disciplined, brave, and united.","zh":"講者相信隊伍正在變得有紀律、勇敢和團結。"}],"source":"2022 Q4.pdf","sourcePage":8},{"front":"talent helped us score","meaning":"天分幫助我們得分","examples":[{"en":"Talent helped us score, but discipline kept us improving.","zh":"天分幫助我們得分，但紀律令我們持續進步。"},{"en":"Talent helped us score means natural ability helped the team get points.","zh":"天分幫助我們得分，意思是自然能力幫助隊伍取得分數。"},{"en":"A skilled shooter’s talent may help a team score in a close game.","zh":"技術好的射手的天分可能在接近比賽中幫助隊伍得分。"},{"en":"Talent can produce moments of success, but discipline creates steady progress.","zh":"天分可以帶來成功時刻，但紀律創造穩定進步。"},{"en":"The speaker respects talent but values discipline more for the future.","zh":"講者尊重天分，但更重視紀律對未來的作用。"}],"source":"2022 Q4.pdf","sourcePage":8},{"front":"return to training","meaning":"回到訓練","examples":[{"en":"Discipline helped us return to training after a bad game.","zh":"紀律幫助我們在打得差的一場比賽後回到訓練。"},{"en":"To return to training means to go back to practice after rest, failure, or a match.","zh":"回到訓練，意思是在休息、失敗或比賽後再次練習。"},{"en":"After losing badly, a team must return to training instead of hiding from mistakes.","zh":"大敗後，隊伍必須回到訓練，而不是逃避錯誤。"},{"en":"Returning to training shows responsibility because improvement needs work.","zh":"回到訓練顯示責任感，因為進步需要努力。"},{"en":"The team returned to training because it wanted to grow from poor performances.","zh":"隊伍回到訓練，因為它想從差劣表現中成長。"}],"source":"2022 Q4.pdf","sourcePage":8},{"front":"after a bad game","meaning":"在打得差的一場比賽後","examples":[{"en":"We returned to training after a bad game.","zh":"我們在打得差的一場比賽後回到訓練。"},{"en":"After a bad game means following a match in which the team performed poorly.","zh":"在打得差的一場比賽後，意思是在隊伍表現欠佳的比賽之後。"},{"en":"A player may feel embarrassed after a bad game but still attend practice.","zh":"球員在打得差的一場比賽後可能尷尬，但仍出席練習。"},{"en":"What a team does after a bad game shows its character.","zh":"隊伍在打得差的一場比賽後做甚麼，顯示其品格。"},{"en":"The team chose work instead of excuses after a bad game.","zh":"隊伍在差劣比賽後選擇努力，而不是藉口。"}],"source":"2022 Q4.pdf","sourcePage":8},{"front":"height helped us rebound","meaning":"身高幫助我們搶籃板","examples":[{"en":"Height helped us rebound during important games.","zh":"身高在重要比賽中幫助我們搶籃板。"},{"en":"Height helped us rebound means taller players made it easier to catch missed shots.","zh":"身高幫助我們搶籃板，意思是較高的球員令接住投失的球更容易。"},{"en":"In basketball, height can help players reach the ball above others.","zh":"在籃球中，身高可以幫助球員在別人之上碰到球。"},{"en":"Height is useful, but rebounding also needs timing, strength, and desire.","zh":"身高有用，但搶籃板也需要時機、力量和意志。"},{"en":"The speaker says physical advantages helped, but trust mattered too.","zh":"講者說身體優勢有幫助，但信任也重要。"}],"source":"2022 Q4.pdf","sourcePage":8},{"front":"trust helped us rotate","meaning":"信任幫助我們輪轉防守","examples":[{"en":"Trust helped us rotate, cover and communicate.","zh":"信任幫助我們輪轉、防守補位和溝通。"},{"en":"Trust helped us rotate means players could change defensive positions because they believed teammates would do their jobs.","zh":"信任幫助我們輪轉防守，意思是球員相信隊友會做好角色，所以能轉換防守位置。"},{"en":"In defence, trust allows one player to leave a space because another player will cover it.","zh":"在防守中，信任讓一名球員離開某空位，因為另一名球員會補上。"},{"en":"Without trust, players hesitate and the defence breaks down.","zh":"沒有信任，球員會猶豫，防守就會崩潰。"},{"en":"The team’s defence improved because trust made movement smoother.","zh":"隊伍防守進步，因為信任令移動更流暢。"}],"source":"2022 Q4.pdf","sourcePage":8},{"front":"rotate, cover and communicate","meaning":"輪轉、補位和溝通","examples":[{"en":"Good defence requires players to rotate, cover and communicate.","zh":"良好防守要求球員輪轉、補位和溝通。"},{"en":"Rotate, cover and communicate means move to new positions, protect open spaces, and talk clearly.","zh":"輪轉、補位和溝通，意思是移到新位置、保護空位，並清楚說話。"},{"en":"Basketball defenders rotate when an opponent drives toward the basket.","zh":"當對手切入籃底，籃球防守球員會輪轉。"},{"en":"Teams defend better when players cover one another and communicate early.","zh":"當球員互相補位並及早溝通，隊伍防守會更好。"},{"en":"The team learned that defence is shared movement, not individual effort only.","zh":"隊伍學會防守是共同移動，而不只是個人努力。"}],"source":"2022 Q4.pdf","sourcePage":8},{"front":"speed helped us attack","meaning":"速度幫助我們進攻","examples":[{"en":"Speed helped us attack quickly.","zh":"速度幫助我們快速進攻。"},{"en":"Speed helped us attack means quick movement allowed the team to create scoring chances.","zh":"速度幫助我們進攻，意思是快速移動讓隊伍創造得分機會。"},{"en":"A fast guard can help a basketball team attack before defenders are ready.","zh":"快速後衛可以在防守球員準備好之前幫助籃球隊進攻。"},{"en":"Speed is useful when players use it with control and teamwork.","zh":"當球員有控制和團隊合作地運用速度，速度就很有用。"},{"en":"The team’s speed created chances, but discipline made those chances better.","zh":"隊伍的速度創造機會，但紀律令那些機會更好。"}],"source":"2022 Q4.pdf","sourcePage":9},{"front":"humility helped us accept criticism","meaning":"謙卑幫助我們接受批評","examples":[{"en":"Humility helped us accept criticism without blaming one another.","zh":"謙卑幫助我們接受批評，而不互相責怪。"},{"en":"Humility helped us accept criticism means modesty allowed players to listen to feedback instead of becoming defensive.","zh":"謙卑幫助我們接受批評，意思是謙遜讓球員聆聽回饋，而不是變得防衛。"},{"en":"A good player accepts a coach’s correction because they want to improve.","zh":"好球員接受教練糾正，因為他想進步。"},{"en":"Humility makes criticism useful because people stop protecting their pride.","zh":"謙卑令批評變得有用，因為人們停止保護自己的面子。"},{"en":"The team improved when players accepted feedback without attacking one another.","zh":"當球員接受回饋而不互相攻擊，隊伍就進步。"}],"source":"2022 Q4.pdf","sourcePage":9},{"front":"accept criticism","meaning":"接受批評","examples":[{"en":"Good players learn to accept criticism.","zh":"好球員學會接受批評。"},{"en":"To accept criticism means to listen to comments about mistakes and use them to improve.","zh":"接受批評，意思是聆聽關於錯誤的意見，並用它們改善。"},{"en":"A student accepts criticism when they revise an essay after teacher feedback.","zh":"學生根據老師回饋修改文章，就是接受批評。"},{"en":"Accepting criticism is difficult because it can hurt pride.","zh":"接受批評很難，因為它可能傷害自尊。"},{"en":"The team learned to accept criticism as part of becoming stronger.","zh":"隊伍學會把接受批評視為變得更強的一部分。"}],"source":"2022 Q4.pdf","sourcePage":9},{"front":"without blaming one another","meaning":"不互相責怪","examples":[{"en":"We accepted criticism without blaming one another.","zh":"我們接受批評，而不互相責怪。"},{"en":"Without blaming one another means without accusing teammates or shifting fault onto them.","zh":"不互相責怪，意思是不指責隊友或把錯推到他們身上。"},{"en":"A group project improves when students discuss mistakes without blaming one another.","zh":"當學生不互相責怪而討論錯誤，小組專題會改善。"},{"en":"Blame can break trust, but honest discussion can build it.","zh":"責怪會破壞信任，但誠實討論可以建立信任。"},{"en":"The team stayed united because criticism did not become personal attack.","zh":"隊伍保持團結，因為批評沒有變成人身攻擊。"}],"source":"2022 Q4.pdf","sourcePage":9},{"front":"not so much…as…","meaning":"與其說是……不如說是……","examples":[{"en":"It is not so much talent as discipline that determines long-term success.","zh":"決定長遠成功的與其說是天分，不如說是紀律。"},{"en":"Not so much A as B means B is the more important explanation than A.","zh":"與其說是 A，不如說是 B，意思是 B 比 A 更能解釋真正原因。"},{"en":"Exam success is not so much luck as steady preparation.","zh":"考試成功與其說是運氣，不如說是穩定準備。"},{"en":"This structure helps writers correct what people may overvalue.","zh":"這個結構幫助作者糾正人們可能過分重視的東西。"},{"en":"The speaker says discipline matters more than talent over time.","zh":"講者說長遠而言，紀律比天分更重要。"}],"source":"2022 Q4.pdf","sourcePage":9},{"front":"determine long-term success","meaning":"決定長遠成功","examples":[{"en":"Discipline determines long-term success.","zh":"紀律決定長遠成功。"},{"en":"To determine long-term success means to decide whether someone continues to succeed over time.","zh":"決定長遠成功，意思是判定某人能否隨時間持續成功。"},{"en":"Daily practice may determine long-term success more than one lucky performance.","zh":"每天練習可能比一次幸運表現更能決定長遠成功。"},{"en":"Long-term success depends on habits that survive both victory and failure.","zh":"長遠成功依靠能經得起勝利和失敗的習慣。"},{"en":"The team believes discipline will determine whether silver becomes a beginning.","zh":"隊伍相信紀律會決定銀牌是否成為開始。"}],"source":"2022 Q4.pdf","sourcePage":9},{"front":"whether we are seniors, juniors or graduates","meaning":"不論我們是高年級、低年級還是畢業生","examples":[{"en":"Whether we are seniors, juniors or graduates, we must keep this culture alive.","zh":"不論我們是高年級、低年級還是畢業生，我們都必須延續這種文化。"},{"en":"Whether we are seniors, juniors or graduates means no matter what stage of school life we are in.","zh":"不論我們是高年級、低年級還是畢業生，意思是不管我們處於學校生活哪個階段。"},{"en":"Whether students are new members or team leaders, they should respect the same values.","zh":"不論學生是新成員還是隊伍領袖，都應尊重同樣價值。"},{"en":"A strong culture continues when different generations protect it together.","zh":"當不同世代一起保護文化，強大文化才能延續。"},{"en":"The speaker asks everyone, past and present, to carry the team spirit forward.","zh":"講者請過去和現在的每個人把隊伍精神傳承下去。"}],"source":"2022 Q4.pdf","sourcePage":9},{"front":"watching from the stands","meaning":"在看台上觀看","examples":[{"en":"Graduates may watch future games from the stands.","zh":"畢業生可能在看台上觀看未來比賽。"},{"en":"Watching from the stands means sitting in the spectator area and viewing the match.","zh":"在看台上觀看，意思是坐在觀眾席觀看比賽。"},{"en":"Former players may watch from the stands and cheer for younger teammates.","zh":"前球員可能在看台上觀看，並為年輕隊友打氣。"},{"en":"Watching from the stands can still be a form of support.","zh":"在看台上觀看仍可以是一種支持。"},{"en":"Graduates may no longer play, but they can keep the culture alive from the stands.","zh":"畢業生可能不再上場，但仍可以在看台上延續文化。"}],"source":"2022 Q4.pdf","sourcePage":9},{"front":"keep this culture alive","meaning":"延續這種文化","examples":[{"en":"We must keep this team culture alive.","zh":"我們必須延續這種團隊文化。"},{"en":"To keep this culture alive means to continue the team’s values, habits, and spirit.","zh":"延續這種文化，意思是繼續保持隊伍的價值觀、習慣和精神。"},{"en":"Older students keep a club culture alive by teaching new members patiently.","zh":"高年級學生耐心教導新成員，就是延續學會文化。"},{"en":"Culture stays alive only when people practise it, not just talk about it.","zh":"文化只有在人們實踐它，而不只是談論它時，才會保持生命力。"},{"en":"The team must keep its culture alive through discipline, trust, and humility.","zh":"隊伍必須透過紀律、信任和謙卑延續其文化。"}],"source":"2022 Q4.pdf","sourcePage":9},{"front":"train earlier","meaning":"更早開始訓練","examples":[{"en":"Next year, we must train earlier.","zh":"明年，我們必須更早開始訓練。"},{"en":"Train earlier means begin practice sooner or at an earlier stage.","zh":"更早開始訓練，意思是更早或在較早階段開始練習。"},{"en":"A team may train earlier before a difficult tournament.","zh":"隊伍可能在困難賽事前更早開始訓練。"},{"en":"Training earlier gives players more time to build fitness and teamwork.","zh":"更早訓練給球員更多時間建立體能和合作。"},{"en":"The speaker wants next year’s team to prepare sooner than before.","zh":"講者希望明年的隊伍比以往更早準備。"}],"source":"2022 Q4.pdf","sourcePage":9},{"front":"listen harder","meaning":"更用心聆聽","examples":[{"en":"We must listen harder during training.","zh":"我們在訓練中必須更用心聆聽。"},{"en":"Listen harder means pay closer attention and take advice more seriously.","zh":"更用心聆聽，意思是更專注並更認真接受建議。"},{"en":"A player listens harder when they ask the coach how to fix a mistake.","zh":"當球員問教練如何修正錯誤，就是更用心聆聽。"},{"en":"Listening harder helps teams improve because feedback is not wasted.","zh":"更用心聆聽幫助隊伍進步，因為回饋不會被浪費。"},{"en":"The speaker asks players to listen harder so training becomes more useful.","zh":"講者要求球員更用心聆聽，讓訓練更有用。"}],"source":"2022 Q4.pdf","sourcePage":10},{"front":"hold one another accountable","meaning":"互相督促；互相問責","examples":[{"en":"Teammates should hold one another accountable.","zh":"隊友應互相督促。"},{"en":"To hold one another accountable means to remind each other to meet responsibilities and standards.","zh":"互相督促或互相問責，意思是提醒彼此履行責任和達到標準。"},{"en":"Players hold one another accountable when they ask teammates not to skip training.","zh":"當球員要求隊友不要缺席訓練，就是互相督促。"},{"en":"Accountability works best when it comes with respect, not blame.","zh":"問責如果帶着尊重而不是責怪，效果最好。"},{"en":"A strong team holds one another accountable because everyone’s effort affects everyone else.","zh":"強大隊伍會互相督促，因為每個人的努力都影響其他人。"}],"source":"2022 Q4.pdf","sourcePage":10},{"front":"be ashamed of second place","meaning":"為第二名感到羞愧","examples":[{"en":"We are not ashamed of second place.","zh":"我們不為第二名感到羞愧。"},{"en":"To be ashamed of second place means to feel shame because the team finished second.","zh":"為第二名感到羞愧，意思是因隊伍得第二名而感到羞恥。"},{"en":"Players should not be ashamed of second place if they gave everything fairly.","zh":"如果球員公平地付出一切，就不應為第二名感到羞愧。"},{"en":"Second place can hurt without being shameful.","zh":"第二名可以令人難受，但不一定令人羞愧。"},{"en":"The speaker says the team should feel proud of its effort, not ashamed of silver.","zh":"講者說隊伍應為努力自豪，而不是為銀牌羞愧。"}],"source":"2022 Q4.pdf","sourcePage":10},{"front":"respect how close we came to first","meaning":"尊重自己曾經多接近第一","examples":[{"en":"We train harder because we respect how close we came to first.","zh":"我們更努力訓練，因為我們尊重自己曾經多接近第一。"},{"en":"To respect how close we came to first means to recognise that the team was near victory and should honour that effort.","zh":"尊重自己曾經多接近第一，意思是承認隊伍曾接近勝利，並珍惜那份努力。"},{"en":"A runner who loses by one second may respect how close they came and train harder.","zh":"以一秒落敗的跑手可能尊重自己曾多接近勝利，並更努力訓練。"},{"en":"Close results can motivate people when they see progress instead of failure only.","zh":"當人們看見進步而不只看見失敗，接近的結果可以激勵人。"},{"en":"The team respects its near success by preparing better for next season.","zh":"隊伍透過為下季準備得更好，尊重自己曾接近成功。"}],"source":"2022 Q4.pdf","sourcePage":10},{"front":"celebrate properly","meaning":"好好慶祝","examples":[{"en":"Tonight, let us celebrate properly.","zh":"今晚，讓我們好好慶祝。"},{"en":"Celebrate properly means enjoy and honour an achievement in a full and meaningful way.","zh":"好好慶祝，意思是完整而有意義地享受和肯定一項成就。"},{"en":"A team should celebrate properly after a season of hard work, even without first place.","zh":"經歷一季努力後，即使沒有第一名，隊伍也應好好慶祝。"},{"en":"Proper celebration includes gratitude, laughter, and honest reflection.","zh":"好好慶祝包括感謝、笑聲和誠實反思。"},{"en":"The speaker wants the team to celebrate effort, growth, and unity.","zh":"講者希望隊伍慶祝努力、成長和團結。"}],"source":"2022 Q4.pdf","sourcePage":10},{"front":"clap for","meaning":"為……鼓掌","examples":[{"en":"Let us clap for the players who improved quietly.","zh":"讓我們為默默進步的球員鼓掌。"},{"en":"To clap for someone means to applaud them to show praise or support.","zh":"為某人鼓掌，意思是拍手表示讚賞或支持。"},{"en":"The class clapped for the student who finally gave a confident speech.","zh":"全班為終於自信演講的學生鼓掌。"},{"en":"Clapping for quiet improvement helps people feel seen.","zh":"為默默進步鼓掌，幫助人感到被看見。"},{"en":"The captain asks everyone to clap for players whose progress was not always obvious.","zh":"隊長請大家為進步未必總是明顯的球員鼓掌。"}],"source":"2022 Q4.pdf","sourcePage":10},{"front":"improve quietly","meaning":"默默進步","examples":[{"en":"Some players improved quietly throughout the season.","zh":"有些球員整個賽季都默默進步。"},{"en":"Improve quietly means get better without attracting much attention.","zh":"默默進步，意思是在不太引人注意的情況下變得更好。"},{"en":"A student may improve quietly by practising every night without telling others.","zh":"學生可能每晚練習而不告訴別人，默默進步。"},{"en":"Quiet improvement matters because progress is not always dramatic.","zh":"默默進步很重要，因為進步不一定戲劇化。"},{"en":"The team celebrates players who improved quietly but consistently.","zh":"隊伍慶祝那些默默但持續進步的球員。"}],"source":"2022 Q4.pdf","sourcePage":10},{"front":"laugh about","meaning":"笑談","examples":[{"en":"Let us laugh about the drills we secretly hated.","zh":"讓我們笑談那些我們暗地裏討厭的訓練項目。"},{"en":"To laugh about something means to remember it with humour instead of anger.","zh":"笑談某事，意思是帶着幽默而不是憤怒去回憶它。"},{"en":"Students may laugh about a difficult camp after it is over.","zh":"學生可能在艱苦營會結束後笑談它。"},{"en":"Laughing about hard training can turn shared suffering into shared memory.","zh":"笑談艱苦訓練可以把共同受苦變成共同記憶。"},{"en":"The team can now laugh about painful drills because they survived them together.","zh":"隊伍現在可以笑談痛苦訓練，因為他們一起熬過了。"}],"source":"2022 Q4.pdf","sourcePage":10},{"front":"drills","meaning":"訓練項目","examples":[{"en":"We laughed about the drills we secretly hated.","zh":"我們笑談那些暗地裏討厭的訓練項目。"},{"en":"Drills are repeated training exercises used to build skill, speed, or fitness.","zh":"訓練項目，是用來建立技巧、速度或體能的反覆練習。"},{"en":"Basketball drills may include shooting practice, defensive slides, and sprints.","zh":"籃球訓練項目可能包括投籃練習、防守滑步和衝刺。"},{"en":"Drills can feel boring, but they make skills more automatic.","zh":"訓練項目可能沉悶，但它們令技巧更自然。"},{"en":"The team’s hated drills later became part of its shared humour.","zh":"隊伍討厭的訓練項目後來成為共同笑話的一部分。"}],"source":"2022 Q4.pdf","sourcePage":10},{"front":"secretly hated","meaning":"暗地裏討厭","examples":[{"en":"We remembered the drills we secretly hated.","zh":"我們記得那些暗地裏討厭的訓練項目。"},{"en":"Secretly hated means disliked privately without saying so openly.","zh":"暗地裏討厭，意思是私下不喜歡，但沒有公開說出來。"},{"en":"A student may secretly hate early morning practice but still attend every session.","zh":"學生可能暗地裏討厭清晨練習，但仍出席每一節。"},{"en":"Secret dislikes can become funny memories after the hard work is over.","zh":"辛苦結束後，私下討厭的事情可以變成有趣回憶。"},{"en":"The team secretly hated some drills, yet those drills helped them improve.","zh":"隊伍暗地裏討厭某些訓練項目，但那些項目幫助他們進步。"}],"source":"2022 Q4.pdf","sourcePage":10},{"front":"believe in us","meaning":"相信我們","examples":[{"en":"We should thank the people who believed in us.","zh":"我們應感謝那些相信我們的人。"},{"en":"To believe in us means to trust our ability, effort, and potential.","zh":"相信我們，意思是信任我們的能力、努力和潛力。"},{"en":"A coach believes in players when they encourage them after mistakes.","zh":"教練在球員犯錯後鼓勵他們，就是相信他們。"},{"en":"Belief from others can help a team continue when confidence is low.","zh":"來自他人的信任可以在信心低落時幫助隊伍繼續。"},{"en":"The team thanked everyone who believed in them before results proved anything.","zh":"隊伍感謝在結果證明任何事之前已相信他們的人。"}],"source":"2022 Q4.pdf","sourcePage":11},{"front":"before the scoreboard did","meaning":"在計分牌證明之前","examples":[{"en":"Some people believed in us before the scoreboard did.","zh":"有些人在計分牌證明之前已相信我們。"},{"en":"Before the scoreboard did means before official results showed success.","zh":"在計分牌證明之前，意思是在官方結果顯示成功之前。"},{"en":"A teacher may believe in a student before the exam marks show improvement.","zh":"老師可能在考試分數顯示進步之前已相信學生。"},{"en":"Belief before proof can give people courage to keep working.","zh":"在證明之前的信任，可以給人繼續努力的勇氣。"},{"en":"The parents and coaches believed in the team before the scoreboard showed its progress.","zh":"家長和教練在計分牌顯示進步之前已相信隊伍。"}],"source":"2022 Q4.pdf","sourcePage":11},{"front":"take one promise with us","meaning":"帶着一個承諾離開","examples":[{"en":"Let us take one promise with us after this dinner.","zh":"讓我們在這場晚宴後帶着一個承諾離開。"},{"en":"To take one promise with us means to leave with a clear commitment for the future.","zh":"帶着一個承諾離開，意思是帶着對未來的清晰承擔離開。"},{"en":"After a camp, students may take one promise with them to support one another more.","zh":"營會後，學生可能帶着要更支持彼此的承諾離開。"},{"en":"A promise helps a celebration become the beginning of action.","zh":"一個承諾幫助慶祝變成行動的開始。"},{"en":"The speaker asks the team to leave dinner with a promise to keep improving.","zh":"講者請隊伍在晚宴後帶着繼續進步的承諾離開。"}],"source":"2022 Q4.pdf","sourcePage":11},{"front":"not be a full stop","meaning":"不是句號","examples":[{"en":"This silver medal will not be a full stop.","zh":"這面銀牌不是句號。"},{"en":"Not be a full stop means not be the final ending of the story.","zh":"不是句號，意思不是故事的最終結束。"},{"en":"A poor test result should not be a full stop in a student’s learning.","zh":"一次差的測驗成績不應成為學生學習的句號。"},{"en":"A result becomes a full stop only if people stop trying after it.","zh":"只有當人們在結果後停止嘗試，它才會變成句號。"},{"en":"The speaker says silver is not the end because the team will rise again.","zh":"講者說銀牌不是終點，因為隊伍會重新振作。"}],"source":"2022 Q4.pdf","sourcePage":11},{"front":"be a comma","meaning":"是逗號；是未完待續","examples":[{"en":"This silver medal will be a comma, not an ending.","zh":"這面銀牌是逗號，不是結束。"},{"en":"Be a comma means be a pause before the story continues.","zh":"是逗號，意思是在故事繼續之前的一個停頓。"},{"en":"A difficult year can be a comma if students use it to begin again.","zh":"如果學生用困難一年重新開始，那一年可以是逗號。"},{"en":"A comma suggests continuation, not final failure.","zh":"逗號暗示延續，而不是最終失敗。"},{"en":"The team treats silver as a comma before its next comeback.","zh":"隊伍把銀牌視為下一次捲土重來前的逗號。"}],"source":"2022 Q4.pdf","sourcePage":11},{"front":"to my teammates","meaning":"致我的隊友","examples":[{"en":"To my teammates: I am proud of you.","zh":"致我的隊友：我為你們感到自豪。"},{"en":"To my teammates is a direct address to the people who played on the same team.","zh":"致我的隊友，是直接向同隊球員說話。"},{"en":"A captain may begin a speech with “to my teammates” before thanking them.","zh":"隊長可能在感謝隊友前，以「致我的隊友」開始演說。"},{"en":"Direct address makes a message feel personal and sincere.","zh":"直接稱呼令信息感覺個人化和真誠。"},{"en":"The speaker uses “to my teammates” to speak from the heart.","zh":"講者使用「致我的隊友」來真心說話。"}],"source":"2022 Q4.pdf","sourcePage":11},{"front":"be proud of","meaning":"為……感到自豪","examples":[{"en":"I am proud of every teammate on this team.","zh":"我為這支隊伍的每位隊友感到自豪。"},{"en":"To be proud of someone means to feel pleased and honoured by what they have done or become.","zh":"為某人感到自豪，意思是因某人的行為或成長而感到高興和光榮。"},{"en":"A coach is proud of players who keep training after defeat.","zh":"教練為落敗後仍繼續訓練的球員感到自豪。"},{"en":"Pride can come from effort and character, not only winning.","zh":"自豪可以來自努力和品格，而不只是勝利。"},{"en":"The captain is proud of the team because it grew together.","zh":"隊長為隊伍感到自豪，因為大家一起成長。"}],"source":"2022 Q4.pdf","sourcePage":11},{"front":"not merely because","meaning":"不只是因為","examples":[{"en":"I am proud not merely because we reached a final.","zh":"我感到自豪，不只是因為我們打入決賽。"},{"en":"Not merely because means not only for that reason.","zh":"不只是因為，意思是不僅僅由於那個原因。"},{"en":"A teacher may be proud not merely because students won, but because they helped one another.","zh":"老師可能感到自豪，不只是因為學生勝出，而是因為他們互相幫助。"},{"en":"This phrase prepares readers for a deeper reason.","zh":"這個短語為讀者準備一個更深層原因。"},{"en":"The captain is proud because the team became worth leading, not only because it reached the final.","zh":"隊長自豪，是因為隊伍變成值得帶領，而不只是因為打入決賽。"}],"source":"2022 Q4.pdf","sourcePage":11},{"front":"reach a final","meaning":"打入決賽","examples":[{"en":"We reached a final through discipline and teamwork.","zh":"我們透過紀律和團隊合作打入決賽。"},{"en":"To reach a final means to qualify for the last match of a competition.","zh":"打入決賽，意思是取得參加比賽最後一場的資格。"},{"en":"A team may reach a final after winning several difficult games.","zh":"隊伍可能在贏得幾場艱難比賽後打入決賽。"},{"en":"Reaching a final shows achievement, but how the team gets there also matters.","zh":"打入決賽顯示成就，但隊伍如何走到那裏也重要。"},{"en":"The team reached the final because players trusted the process.","zh":"隊伍打入決賽，因為球員相信過程。"}],"source":"2022 Q4.pdf","sourcePage":11},{"front":"a team worth leading","meaning":"一支值得帶領的隊伍","examples":[{"en":"We became a team worth leading.","zh":"我們成為一支值得帶領的隊伍。"},{"en":"A team worth leading is a team whose effort, attitude, and unity make leadership meaningful.","zh":"一支值得帶領的隊伍，是努力、態度和團結令領導變得有意義的隊伍。"},{"en":"A captain feels proud to lead players who listen, work hard, and support one another.","zh":"隊長會為帶領願意聆聽、努力和互相支持的球員感到自豪。"},{"en":"A team becomes worth leading when members care about more than themselves.","zh":"當成員關心的不只是自己，隊伍就變得值得帶領。"},{"en":"The speaker values the team because its character made leadership an honour.","zh":"講者珍惜這支隊伍，因為其品格令領導成為榮幸。"}],"source":"2022 Q4.pdf","sourcePage":11},{"front":"one day","meaning":"有一天","examples":[{"en":"One day, the crowd will forget the score.","zh":"有一天，觀眾會忘記比數。"},{"en":"One day means at some time in the future.","zh":"有一天，意思是在未來某個時間。"},{"en":"One day, students may forget the test mark but remember the teacher’s encouragement.","zh":"有一天，學生可能忘記測驗分數，但記得老師的鼓勵。"},{"en":"This phrase helps speakers look beyond the present moment.","zh":"這個短語幫助講者看得比當下更遠。"},{"en":"One day, the score will fade, but the team’s unity will remain.","zh":"有一天，比數會淡去，但隊伍的團結會留下。"}],"source":"2022 Q4.pdf","sourcePage":12},{"front":"forget the score","meaning":"忘記比數","examples":[{"en":"The crowd may forget the score one day.","zh":"觀眾有一天可能會忘記比數。"},{"en":"To forget the score means to stop remembering the exact result of a match.","zh":"忘記比數，意思是不再記得比賽的確切結果。"},{"en":"Fans may forget the score but remember a player’s courage.","zh":"球迷可能忘記比數，但記得球員的勇氣。"},{"en":"Scores fade because numbers matter less than stories over time.","zh":"比數會淡去，因為時間久了，故事比數字更重要。"},{"en":"The speaker believes people will forget the score but remember how the team stood together.","zh":"講者相信人們會忘記比數，但記得隊伍如何並肩而立。"}],"source":"2022 Q4.pdf","sourcePage":12},{"front":"details of the match","meaning":"比賽細節","examples":[{"en":"We may forget details of the match.","zh":"我們可能會忘記比賽細節。"},{"en":"Details of the match are the small facts and moments from a game.","zh":"比賽細節，是一場比賽中的小事實和時刻。"},{"en":"Players may forget details such as who scored in the second quarter.","zh":"球員可能忘記第二節是誰得分等細節。"},{"en":"Small details may fade, but the feeling of the match can remain.","zh":"小細節可能淡去，但比賽感覺可以留下。"},{"en":"The team may forget details of the match but remember its shared courage.","zh":"隊伍可能忘記比賽細節，但記得共同勇氣。"}],"source":"2022 Q4.pdf","sourcePage":12},{"front":"stand together","meaning":"並肩而立","examples":[{"en":"We will remember how we stood together.","zh":"我們會記得自己如何並肩而立。"},{"en":"To stand together means to remain united and support one another.","zh":"並肩而立，意思是保持團結並互相支持。"},{"en":"A team stands together when it protects a teammate after a mistake.","zh":"當隊伍在隊友犯錯後保護他，就是並肩而立。"},{"en":"Standing together matters most when the result is painful.","zh":"當結果令人痛苦時，並肩而立最重要。"},{"en":"The players stood together after defeat instead of blaming one another.","zh":"球員落敗後並肩而立，而不是互相責怪。"}],"source":"2022 Q4.pdf","sourcePage":12},{"front":"lose with dignity","meaning":"有尊嚴地落敗","examples":[{"en":"We lost with dignity after giving everything.","zh":"我們付出一切後有尊嚴地落敗。"},{"en":"To lose with dignity means to accept defeat with respect, courage, and self-control.","zh":"有尊嚴地落敗，意思是以尊重、勇氣和自制接受失敗。"},{"en":"A player loses with dignity when they shake hands after a close loss.","zh":"球員在接近落敗後握手，就是有尊嚴地落敗。"},{"en":"Losing with dignity shows character because disappointment does not turn into bitterness.","zh":"有尊嚴地落敗顯示品格，因為失望沒有變成怨恨。"},{"en":"The team lost with dignity because it had given everything fairly.","zh":"隊伍有尊嚴地落敗，因為他們公平地付出了一切。"}],"source":"2022 Q4.pdf","sourcePage":12},{"front":"rise again","meaning":"重新振作","examples":[{"en":"We chose to rise again after defeat.","zh":"我們選擇在失敗後重新振作。"},{"en":"To rise again means to recover, stand up, and continue after failure or pain.","zh":"重新振作，意思是在失敗或痛苦後恢復、站起來並繼續。"},{"en":"A student can rise again after a poor result by changing their study habits.","zh":"學生可以在成績不佳後透過改變學習習慣重新振作。"},{"en":"Teams rise again when they turn disappointment into training.","zh":"當隊伍把失望轉化為訓練，它們就會重新振作。"},{"en":"The speaker believes this team will rise again because it has discipline and unity.","zh":"講者相信這支隊伍會重新振作，因為它有紀律和團結。"}],"source":"2022 Q4.pdf","sourcePage":12},{"front":"let this be the beginning of","meaning":"讓這成為……的開始","examples":[{"en":"Let this be the beginning of our next comeback.","zh":"讓這成為我們下一次捲土重來的開始。"},{"en":"Let this be the beginning of means allow this moment to start something new.","zh":"讓這成為……的開始，意思是讓這一刻啟動新的事情。"},{"en":"After a difficult exam, a student may say, “Let this be the beginning of better habits.”","zh":"困難考試後，學生可能說：「讓這成為更好習慣的開始。」"},{"en":"This phrase turns an ending into a starting point.","zh":"這個短語把一個結束轉化為起點。"},{"en":"The captain wants the silver medal to begin the team’s next chapter.","zh":"隊長希望銀牌成為隊伍下一章的開始。"}],"source":"2022 Q4.pdf","sourcePage":12},{"front":"next comeback","meaning":"下一次捲土重來","examples":[{"en":"This dinner marks the beginning of our next comeback.","zh":"這場晚宴標誌着我們下一次捲土重來的開始。"},{"en":"Next comeback means the next effort to return stronger after defeat.","zh":"下一次捲土重來，意思是在失敗後下一次以更強姿態回來的努力。"},{"en":"A team’s next comeback may begin with honest reflection and harder training.","zh":"隊伍的下一次捲土重來可能由誠實反思和更努力訓練開始。"},{"en":"Comebacks require patience because improvement does not happen overnight.","zh":"捲土重來需要耐性，因為進步不會一夜之間發生。"},{"en":"The team sees the dinner not as an ending, but as the start of its next comeback.","zh":"隊伍把晚宴看成不是結束，而是下一次捲土重來的開始。"}],"source":"2022 Q4.pdf","sourcePage":12}]};
window.EDMUND_FLASHCARD_SEED = window.EDMUND_FLASHCARD_SEED || {};
